/**
 * StockSelector.js - Stock Selection Component
 * Week 2 - Days 10-14
 */

import React from 'react';
import { motion } from 'framer-motion';

const StockSelector = ({ selectedStock, onStockChange, onPredict, loading, supportedStocks }) => {
  return (
    <div className="stock-selector-card">
      <div className="selector-content">
        <div className="selector-group">
          <label className="selector-label">Select Stock</label>
          <select
            className="stock-select"
            value={selectedStock}
            onChange={(e) => onStockChange(e.target.value)}
            disabled={loading}
          >
            {supportedStocks.length > 0 ? (
              supportedStocks.map((stock) => (
                <option key={stock.ticker} value={stock.ticker}>
                  {stock.ticker} - {stock.name}
                </option>
              ))
            ) : (
              <>
                <option value="AAPL">AAPL - Apple Inc.</option>
                <option value="MSFT">MSFT - Microsoft Corporation</option>
                <option value="GOOGL">GOOGL - Alphabet Inc.</option>
                <option value="TSLA">TSLA - Tesla Inc.</option>
                <option value="AMZN">AMZN - Amazon.com Inc.</option>
                <option value="META">META - Meta Platforms Inc.</option>
                <option value="NVDA">NVDA - NVIDIA Corporation</option>
                <option value="JPM">JPM - JPMorgan Chase & Co.</option>
              </>
            )}
          </select>
        </div>

        <motion.button
          className="predict-button"
          onClick={onPredict}
          disabled={loading}
          whileHover={{ scale: loading ? 1 : 1.05 }}
          whileTap={{ scale: loading ? 1 : 0.95 }}
        >
          {loading ? (
            <>
              <span className="spinner" style={{ width: '16px', height: '16px', borderWidth: '2px' }}></span>
              <span>Predicting...</span>
            </>
          ) : (
            <>
              <span>🔮</span>
              <span>Predict</span>
            </>
          )}
        </motion.button>
      </div>
    </div>
  );
};

export default StockSelector;
